namespace Com\Tecnick\Pdf\Font\Import;

/**
 * Com\Tecnick\Pdf\Font\Import\ProcessorInterface
 *
 * What Import expects of the class it hands a font program to.
 *
 * The processors take different constructor arguments, so only the call Import makes on the
 * one the font type selects is named here.
 *
 * @since     2026-08-14
 * @category  Library
 * @package   PdfFont
 * @author    Nicola Asuni <info@tecnick.com>
 * @copyright 2011-2026 Nicola Asuni - Tecnick.com LTD
 * @license   https://www.gnu.org/copyleft/lesser.html GNU-LGPL v3 (see LICENSE)
 * @link      https://github.com/tecnickcom/tc-lib-pdf-font
 *
 * @phpstan-import-type TFontData from \Com\Tecnick\Pdf\Font\Load
 */
interface ProcessorInterface
{
    /**
     * Returns the font metrics extracted from the program.
     *
     * @return TFontData
     */
    public function getFontMetrics(): array;
}
